import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def calculate_x_k(k, n):
    if n <= 0:
        return 1  # Or handle as error

    numbers = list(range(k, k + n))

    # Calculate LCM iteratively
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

# Parameters to test
N_values = [3, 4, 5]
K_range = range(1, 16) # k=1 through k=15

results = {}

for n in N_values:
    x_k_values = {}
    print(f"--- Results for n = {n} ---")
    for k in K_range:
        x_k = calculate_x_k(k, n)
        x_k_values[k] = x_k
        print(f"x_{k} (n={n}) = {x_k}")
    results[n] = x_k_values

# Check the weak increase condition for k > 10
print("\n--- Checking weak increasing condition (x_{k+1} > x_k for k > 10) ---")
for n in N_values:
    x_k_values = results[n]
    is_weakly_increasing = True

    # Check k=11, 12, 13, 14
    for k in range(11, 15):
        x_k = x_k_values[k]
        x_k_plus_1 = x_k_values[k+1]

        if not (x_k_plus_1 > x_k):
            is_weakly_increasing = False
            print(f"For n={n}: Failed at k={k}. x_{k+1} = {x_k_plus_1}, x_{k} = {x_k}. Since {x_k_plus_1} <= {x_k}, it is not weakly increasing.")
            break

    if is_weakly_increasing:
        print(f"For n={n}: Condition x_{k+1} > x_k holds for k=11, 12, 13, 14 (Numerically checked).")

# Print final structured results for note writing
print("\n--- Structured Results for Notes ---")
for n in N_values:
    print(f"N={n}: {results[n]}")

