import math
from functools import reduce

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def lcm_range(start, end):
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

N = 6
K_MAX = 15
x_values = {}

# 1. Compute x_k for k=1 through k=15
for k in range(1, K_MAX + 1):
    # x_k = lcm(k, k+1, ..., k+N-1)
    x_k = lcm_range(k, k + N - 1)
    x_values[k] = x_k

print("--- Calculated x_k values (k=1 to 15) ---")
for k in range(1, K_MAX + 1):
    print(f"x_{k}: {x_values[k]}")

# 2. Check if x_{k+1} > x_k holds for k > 10 (i.e., k=11, 12, 13, 14)
print("\n--- Checking Weakly Increasing Condition (k > 10) ---")
fails = False
for k in range(11, K_MAX):
    x_k = x_values[k]
    x_k_plus_1 = x_values[k+1]

    if x_k_plus_1 <= x_k:
        print(f"FAIL at k={k}: x_{k+1} = {x_k_plus_1} <= x_k = {x_k}")
        fails = True
    else:
        print(f"PASS at k={k}: x_{k+1} = {x_k_plus_1} > x_k = {x_k}")

if not fails:
    print("\nCondition x_{k+1} > x_k held for k=11, 12, 13, 14.")
else:
    print("\nSequence fails to be weakly increasing for n=6 based on this check.")
